Amount calcDeliveryFee(WMSOrderTrans _wMSOrderTrans)
{
    //todo: need configuration for price component name and price group

    METSalesLinePriceComponent priceComponent = METSalesLinePriceComponent::find(_wMSOrderTrans.inventTransId,"Delivery Fee", "RXE00");

    return priceComponent.Value * _wMSOrderTrans.qty;
}
